import { useSyncExternalStore } from 'react';

// A person's row shows at most one action error (person-error) at a time. Several slots in the row
// (statement, hold, retire) each take an action; the next action taken on the row, or a change to
// its fields, removes whatever error the row showed, whichever slot raised it.
type RowError = { owner: string; message: string };

const errors = new Map<string, RowError>();
const listeners = new Set<() => void>();

function subscribe(listener: () => void) {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

function set(personId: string, owner: string, message: string) {
  if (message === '') errors.delete(personId);
  else errors.set(personId, { owner, message });
  listeners.forEach((l) => l());
}

/** The row's error as this slot shows it ('' when it is none or another slot's), and its setter. */
export function useRowError(personId: string, owner: string): [string, (message: string) => void] {
  const current = useSyncExternalStore(subscribe, () => errors.get(personId));
  const error = current !== undefined && current.owner === owner ? current.message : '';
  return [error, (message: string) => set(personId, owner, message)];
}

/** Remove the row's error, whichever slot raised it: another action was taken on the row. */
export function clearRowError(personId: string) {
  if (errors.has(personId)) set(personId, '', '');
}
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useOnce } from '../../query/useOnce';
import { postJson } from '../../api/http';
import { PersonHead, PersonRow } from '../../slots/defs/personRow';
import type { Person } from '../people/people';
import { useUser } from '../session/session';
import { useRowError } from '../people/rowError';
import { useWatches, watchesKey } from './watch';

function WatchHead() {
  return (
    <>
      <th>Watched</th>
      <th />
    </>
  );
}

// Whether the signed-in user watches the person, and a button that toggles it. A watched person's
// claim settled, approved or re-settled notifies each of their watchers.
function PersonWatch({ sheetId, person }: { sheetId: string; person: Person }) {
  const queryClient = useQueryClient();
  const [user] = useUser();
  const watches = useWatches(sheetId, user);
  const watched = (watches.data ?? []).includes(person.id);
  const [error, setError] = useRowError(person.id, 'watch');
  const once = useOnce();
  const watch = useMutation({
    mutationFn: (on: boolean) =>
      postJson<{ personIds: string[] }>(
        `/api/sheets/${encodeURIComponent(sheetId)}/people/${encodeURIComponent(person.id)}/watch`,
        { on },
        user,
      ),
    onSuccess: (data) => queryClient.setQueryData(watchesKey(sheetId, user), data.personIds),
    onError: () => setError('That person could not be watched.'),
  });

  const toggle = () => {
    setError('');
    once((done) => watch.mutate(!watched, { onSettled: done }));
  };

  return (
    <>
      <td data-testid="person-watched">{watched ? 'yes' : 'no'}</td>
      <td>
        <button
          type="button"
          data-testid="person-watch"
          onClick={toggle}
          disabled={watch.isPending || watches.data === undefined}
        >
          {watched ? 'Unwatch' : 'Watch'}
        </button>
        {error && (
          <p role="alert" data-testid="person-error">
            {error}
          </p>
        )}
      </td>
    </>
  );
}

export const contributions = [
  PersonHead.fill({ order: 45, Component: WatchHead }),
  PersonRow.fill({ order: 45, Component: PersonWatch }),
];
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asFlag, useSearchParam } from '../../url/useSearchParam';

export type Grade = 'A' | 'B' | 'C';
export const GRADES: Grade[] = ['A', 'B', 'C'];

/** A grade in force from a date (yyyy-MM-dd; '' from the beginning of time) until the next one. */
export type GradeFrom = { from: string; grade: Grade };

/** The grade in force on a date (yyyy-MM-dd): the one whose from-date is the latest on or before it. */
export function gradeOn(grades: GradeFrom[], date: string): Grade {
  let best = grades[0];
  for (const g of grades) if (g.from <= date && g.from >= best.from) best = g;
  return best.grade;
}

// `version` is raised by each save; an edit sends the version it was made from. `statementCount`
// is how many statements have been taken for them; `statedTotal` and `statementDate` are the last
// one's due-total and date ('' before the first). `retired` is set once they have a retirement
// date, `retiredFrom` ('' when not retired), whatever that date is. `held` is whether they have any hold; `holds` their holds in the order added (see `Hold`).
// `patronIds` are the ids of the people they name as their patrons. `grade` is the grade in force on
// the sheet's today; `grades` every grade they have been given, by from-date, the first from ''.
// `terms` are their own terms in days, ahead of their grade's and the sheet's ('' for none).
// `contact` is their contact, trimmed and lower-cased ('' for none); no two people on a sheet share one.
export type Person = {
  id: string;
  name: string;
  grade: Grade;
  version: number;
  statementCount: number;
  statedTotal: string;
  statementDate: string;
  retired: boolean;
  retiredFrom: string;
  held: boolean;
  holds: Hold[];
  patronIds: string[];
  grades: GradeFrom[];
  terms: string;
  contact: string;
};

/**
 * A hold on a person: from a date to a date (yyyy-MM-dd; `to` '' when open-ended), both inclusive.
 * An OPEN or PENDING claim of theirs dated within one, unless a statement binds it, counts in no total.
 */
export type Hold = { from: string; to: string };

/** Whether the date (yyyy-MM-dd) is within one of the holds. */
export const heldOn = (holds: Hold[], date: string) =>
  holds.some((h) => h.from <= date && (h.to === '' || date <= h.to));

/**
 * The holds a person's claims count against on the sheet's `today`: their own, and from the day
 * their retirement date is reached (`today` on or after it) one covering every date — their OPEN
 * and PENDING claims, unless a statement binds them, then count in no total.
 */
export const liveHolds = (p: Pick<Person, 'holds' | 'retiredFrom'>, today: string): Hold[] =>
  p.retiredFrom !== '' && today !== '' && p.retiredFrom <= today ? [...p.holds, { from: '', to: '' }] : p.holds;
