  class: net.officefloor.hq.app.person.HandleInvalidPerson
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPerson {
    public void respond(@Val Sheet sheet, @Val Person person, ObjectResponse<PersonResponse> response) {
        response.send(PersonResponse.from(person, sheet.today()));
    }
}

